// products page
const ProductsPage = () => {
  const { data } = useQuery(GET_PRODUCTS);
  return <ProductList products={data?.products} />;
};

// product detail page
const ProductPage = ({ id }) => {
  const { data } = useQuery(GET_PRODUCT, {
    variables: { id },
  });
  return <ProductDetail product={data?.product} />;
};
